        <Link to="/hilfe" className="hover:text-gray-700">Hilfe</Link>
        <span>·</span>
        <a href="https://github.com/achildrenmile/bosarsalog" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">GitHub</a>
        <span>·</span>
