   116→reportsRouter.get('/adif', (req, res) => {
   117→  const { from, to } = req.query;
   118→  if (!from || !to) {
   119→    res.status(400).json({ error: 'from und to Parameter erforderlich (YYYY-MM-DD)' });
   120→    return;
   121→  }
   122→
   123→  const db = getDb();
   124→
   125→  const exercises = db.prepare(
   126→    `SELECT id, date FROM exercises WHERE date >= ? AND date <= ? ORDER BY date ASC`
   127→  ).all(from, to) as { id: string; date: string }[];
   128→
   129→  if (exercises.length === 0) {
   130→    res.status(404).json({ error: 'Keine Übungen im gewählten Zeitraum' });
   131→    return;
   132→  }
   133→
   134→  const ids = exercises.map(e => e.id);
   135→  const placeholders = ids.map(() => '?').join(',');
   136→
   137→  const reports = db.prepare(
   138→    `SELECT sr.readability, sr.strength, sr.db_over_s9, sr.notes, sr.created_at,
   139→      o.callsign, o.name as op_name, o.qth,
   140→      r.short_name, r.frequency_mhz, r.band, r.type,
   141→      e.date as exercise_date
   142→    FROM signal_reports sr
   143→    JOIN operators o ON o.id = sr.operator_id
   144→    JOIN repeaters r ON r.id = sr.repeater_id
   145→    JOIN exercises e ON e.id = sr.exercise_id
   146→    WHERE sr.exercise_id IN (${placeholders})
   147→      AND sr.is_op_marker = 0
   148→      AND sr.readability IS NOT NULL
   149→    ORDER BY e.date, sr.created_at`
   150→  ).all(...ids) as any[];
   151→
   152→  // Build ADIF
   153→  const adifField = (name: string, value: string) => {
   154→    if (!value) return '';
   155→    return `<${name}:${value.length}>${value} `;
   156→  };
   157→
   158→  let adif = '';
   159→
   160→  // Header
   161→  adif += 'ADIF Export from BOS-ARSA Log\n';
   162→  adif += `https://bosarsalog.oeradio.at/\n`;
   163→  adif += `Date range: ${from} to ${to}\n`;
   164→  adif += `QSO count: ${reports.length}\n`;
   165→  adif += '\n';
   166→  adif += adifField('ADIF_VER', '3.1.4');
   167→  adif += adifField('PROGRAMID', 'BOS-ARSA Log');
   168→  adif += adifField('PROGRAMVERSION', '1.0.5');
   169→  adif += '\n<EOH>\n\n';
   170→
   171→  // Records
   172→  for (const r of reports) {
   173→    const qsoDate = r.exercise_date.replace(/-/g, '');
   174→
   175→    // Extract time from created_at (format: "2026-02-16 14:30:00")
   176→    let timeOn = '0900'; // default
   177→    if (r.created_at) {
   178→      const timePart = r.created_at.split(' ')[1];
   179→      if (timePart) {
   180→        timeOn = timePart.replace(/:/g, '').slice(0, 4);
   181→      }
   182→    }
   183→
   184→    // RST: combine readability + strength + optional dB
   185→    const rst = `${r.readability}${r.strength}`;
   186→
   187→    // Frequency in MHz as string
   188→    const freq = r.frequency_mhz ? String(r.frequency_mhz) : '';
   189→
   190→    // Band mapping
   191→    let band = r.band || '';
   192→    if (!band && r.frequency_mhz) {
   193→      if (r.frequency_mhz >= 144 && r.frequency_mhz < 148) band = '2m';
   194→      else if (r.frequency_mhz >= 430 && r.frequency_mhz < 440) band = '70cm';
   195→      else if (r.frequency_mhz >= 1240 && r.frequency_mhz < 1300) band = '23cm';
   196→    }
   197→
   198→    adif += adifField('CALL', r.callsign);
   199→    adif += adifField('QSO_DATE', qsoDate);
   200→    adif += adifField('TIME_ON', timeOn);
   201→    adif += adifField('MODE', 'FM');
   202→    if (band) adif += adifField('BAND', band);
   203→    if (freq) adif += adifField('FREQ', freq);
   204→    adif += adifField('RST_SENT', rst);
   205→    adif += adifField('RST_RCVD', rst);
   206→    if (r.op_name) adif += adifField('NAME', r.op_name);
   207→    if (r.qth) adif += adifField('QTH', r.qth);
   208→    if (r.notes) adif += adifField('COMMENT', r.notes);
   209→    adif += '<EOR>\n';
   210→  }
   211→
   212→  const filename = `BOS-ARSA_QSOs_${from}_${to}.adi`;
   213→  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
   214→  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
   215→  res.send(adif);
   216→});
